import re

def cmp_semver(a, b):
    def parse_version(version_str):
        # Remove build metadata
        if '+' in version_str:
            version_str = version_str.split('+')[0]

        # Split into core version and pre-release
        if '-' in version_str:
            core, prerelease = version_str.split('-', 1)
        else:
            core, prerelease = version_str, ''

        # Parse major.minor.patch
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_ids = []
        if prerelease:
            prerelease_ids = prerelease.split('.')

        return (major, minor, patch), prerelease_ids

    core_a, pre_a = parse_version(a)
    core_b, pre_b = parse_version(b)

    # Compare major.minor.patch
    for i in range(3):
        if core_a[i] < core_b[i]:
            return -1
        elif core_a[i] > core_b[i]:
            return 1

    # If core versions are equal, check pre-release status
    if not pre_a and pre_b:
        return 1  # a has no prerelease, b does -> a > b
    if pre_a and not pre_b:
        return -1  # a has prerelease, b does -> a < b
    if not pre_a and not pre_b:
        return 0

    # Compare pre-release identifiers
    min_len = min(len(pre_a), len(pre_b))
    for i in range(min_len):
        id_a, id_b = pre_a[i], pre_b[i]

        # Check if identifiers are numeric
        is_num_a = id_a.isdigit()
        is_num_b = id_b.isdigit()

        # Numeric identifiers sort before alphanumeric
        if is_num_a and not is_num_b:
            return -1
        if not is_num_a and is_num_b:
            return 1

        # Both numeric or both alphanumeric
        if is_num_a and is_num_b:
            val_a, val_b = int(id_a), int(id_b)
        else:
            # String comparison for alphanumeric
            val_a, val_b = id_a, id_b

        if val_a < val_b:
            return -1
        elif val_a > val_b:
            return 1

    # All compared identifiers are equal; longer list wins (sorts later)
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1

    return 0
