def gitignore_match(pattern, path):
    # Normalize pattern: remove trailing slashes for matching logic
    # but remember if it had a trailing slash (meaning it only matches directories)
    has_trailing_slash = pattern.endswith('/')
    if has_trailing_slash:
        pattern = pattern[:-1]

    # Normalize path: ensure it doesn't end with slash unless it's meant to be a directory
    # But for matching, we'll treat path ending with '/' as directory indicator
    is_dir = path.endswith('/')
    if is_dir:
        path_without_slash = path[:-1]
    else:
        path_without_slash = path

    # Handle special cases
    if pattern == '':
        return False

    # Check for leading slash (root anchor)
    anchored = pattern.startswith('/')
    if anchored:
        pattern = pattern[1:]

    # Check for **/ at the beginning
    if pattern.startswith('**/'):
        # **/ matches zero or more leading directories
        rest_pattern = pattern[3:]

        # Try matching from each directory level of the path
        parts = path_without_slash.split('/')

        # Try matching from each position in the path
        for i in range(len(parts) + 1):
            sub_path = '/'.join(parts[i:])
            if not sub_path:
                continue
            # If rest_pattern is empty, it matches everything after **
            if not rest_pattern:
                return True
            # Try matching the rest pattern against sub_path
            if _match_pattern(rest_pattern, sub_path, anchored=False):
                return True

        # Special case: **/ at start with trailing slash (now removed) means match directories
        if has_trailing_slash:
            # Check if any sub_path is a directory (ends with /)
            for i in range(len(parts)):
                sub_dir = '/'.join(parts[:i+1])
                if _match_pattern(rest_pattern, sub_dir + '/', anchored=False):
                    return True

        return False

    # Handle /** at the end
    if pattern.endswith('/**'):
        root_pattern = pattern[:-3]

        # Match the path against the root part
        if _match_pattern(root_pattern, path_without_slash, anchored=anchored):
            return True

        # Also check if the root pattern matches a prefix of the path
        parts = path_without_slash.split('/')
        for i in range(len(parts)):
            prefix = '/'.join(parts[:i+1])
            if _match_pattern(root_pattern, prefix, anchored=anchored):
                return True

        # For directory matching with trailing slash
        if has_trailing_slash:
            for i in range(len(parts)):
                prefix = '/'.join(parts[:i+1]) + '/'
                if _match_pattern(root_pattern, prefix, anchored=anchored):
                    return True

        return False

    # Handle patterns with slashes (except trailing)
    if '/' in pattern:
        anchored = True

    # For patterns with leading slash, they are already anchored
    if anchored:
        return _match_pattern(pattern, path_without_slash, anchored=True)

    # For non-anchored patterns (no slash), match at any depth
    parts = path_without_slash.split('/')

    # Try matching against each component and its subdirectories
    for i in range(len(parts)):
        sub_path = '/'.join(parts[i:])
        if _match_pattern(pattern, sub_path, anchored=False):
            return True

    # Also check directory variants
    if has_trailing_slash:
        for i in range(len(parts)):
            sub_dir = '/'.join(parts[:i+1]) + '/'
            if _match_pattern(pattern, sub_dir, anchored=False):
