        return bool(re.search('(^|/)' + regex + '$', path))

def _pattern_to_regex(pattern):
    i = 0
    n = len(pattern)
    regex = []

    while i < n:
        c = pattern[i]

        if c == '*':
            # Check for **
            if i + 1 < n and pattern[i+1] == '*':
                # Check for /** or **/
                if i + 2 < n and pattern[i+2] == '/':
                    # **/ matches zero or more directories
                    regex.append('(?:.*/)?')
                    i += 3
                elif i == 0 and n >= 2:
