                    regex.append('.*/')
                    i += 2
                else:
                    # ** in middle or end (but not /**)
                    regex.append('.*')
                    i += 2
            else:
                # Single * matches anything except /
                regex.append('[^/]*')
                i += 1
        elif c == '?':
            # ? matches any single character except /
            regex.append('[^/]')
            i += 1
        elif c == '[':
            # Character class
            j = i + 1
            while j < n and pattern[j] != ']':
                if pattern[j] == '\\' and j + 1 < n:
                    j += 2
                else:
                    j += 1

            if j < n:
