                char_class = char_class.replace('\\', '\\\\')
                # Handle negation: [!abc] -> [^abc]
                if len(char_class) > 1 and char_class[1] == '!':
                    char_class = '[^' + char_class[2:]
                regex.append(char_class)
                i = j + 1
            else:
                # Unmatched bracket, treat as literal
                regex.append(re.escape(c))
                i += 1
        elif c == '\\':
            # Escape next character if it's a special char in gitignore
            if i + 1 < n:
                next_c = pattern[i+1]
                if next_c in '*?[]\\':
                    regex.append(re.escape(next_c))
                    i += 2
                else:
                    regex.append('\\' + re.escape(next_c))
                    i += 2
            else:
                regex.append(re.escape(c))
                i += 1
        elif c == '/':
            # In gitignore, / matches directory separator
            regex.append('/')
            i += 1
        else:
            # Regular character
            regex.append(re.escape(c))
            i += 1

    return ''.join(regex)
