def parse_range(header, size):
    if not header or not header.startswith('bytes='):
        return None

    ranges_str = header[6:]  # Remove 'bytes=' prefix
    if not ranges_str.strip():
        return None

    result = []
    satisfiable_found = False

    for part in ranges_str.split(','):
        part = part.strip()
        if not part:
            continue

        try:
            if '-' not in part:
                return None

            start_str, end_str = part.split('-', 1)
            start_str = start_str.strip()
            end_str = end_str.strip()

            if not start_str and not end_str:
                return None

            if start_str == '' and end_str != '':
                # Suffix range: -500 means last 500 bytes
                suffix_length = int(end_str)
                if suffix_length < 0:
                    return None
                # If suffix length >= size, use whole resource
                start = max(0, size - suffix_length)
                end = size - 1
            elif start_str != '' and end_str == '':
                # Range to end: 500- means from 500 to the end
                start = int(start_str)
                if start < 0:
                    return None
                end = size - 1
            elif start_str != '' and end_str != '':
                # Normal range: 0-499
                start = int(start_str)
                end = int(end_str)
                if start < 0 or end < 0:
                    return None
            else:
                return None

            # Clamp end to size-1 if necessary
            if start >= size:
                continue  # Unsatisfiable range, skip it

            end = min(end, size - 1)

            # Check if range is valid after clamping
            if start > end:
                continue  # Unsatisfiable after clamping

            result.append((start, end))
            satisfiable_found = True

        except (ValueError, TypeError):
            return None

    if not satisfiable_found:
        return None

    return result
