from decimal import Decimal, ROUND_HALF_EVEN

def round_money(amount, places):
    if not isinstance(amount, Decimal):
        amount = Decimal(str(amount))

    # Create quantizer with the specified number of decimal places
    if places >= 0:
        quantize_str = '1.' + '0' * places
    else:
        # For negative places, use scientific notation style quantizer
        quantize_str = '1E' + str(places)

    quantizer = Decimal(quantize_str)
    return amount.quantize(quantizer, rounding=ROUND_HALF_EVEN)
