from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.key_to_freq = {}
        self.freq_to_keys = defaultdict(OrderedDict)
        self.min_freq = 0

    def get(self, key: int) -> int:
        if self.capacity == 0 or key not in self.key_to_freq:
            return -1

        freq = self.key_to_freq[key]
        value = self.freq_to_keys[freq][key]

        # Remove from current frequency list
        del self.freq_to_keys[freq][key]
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        # Add to new frequency list
        self.key_to_freq[key] = freq + 1
        self.freq_to_keys[freq + 1][key] = value

        return value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return

        if key in self.key_to_freq:
            # Update existing key
            freq = self.key_to_freq[key]
            del self.freq_to_keys[freq][key]
            if not self.freq_to_keys[freq]:
                del self.freq_to_keys[freq]
                if self.min_freq == freq:
                    self.min_freq += 1

            # Update frequency and value
            self.key_to_freq[key] = freq + 1
            self.freq_to_keys[freq + 1][key] = value
        else:
            # New key
            if len(self.key_to_freq) >= self.capacity:
                # Evict least frequently used (and least recently used among ties)
                evict_key, _ = self.freq_to_keys[self.min_freq].popitem(last=False)
                del self.key_to_freq[evict_key]
                if not self.freq_to_keys[self.min_freq]:
                    del self.freq_to_keys[self.min_freq]

            # Insert new key with frequency 1
            self.key_to_freq[key] = 1
            self.freq_to_keys[1][key] = value
            self.min_freq = 1
