from datetime import datetime, timedelta

def next_fire(expr, after):
    # Parse and validate cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute, hour, dom, month, dow = fields

    def parse_field(field_str, min_val, max_val):
        """Parse a cron field and return a set of valid values."""
        if not field_str:
            raise ValueError("Empty field")

        values = set()
        parts = field_str.split(',')

        for part in parts:
            if '/' in part:
                base, step = part.split('/')
                try:
                    step = int(step)
                except ValueError:
                    raise ValueError(f"Invalid step value: {step}")
                if step <= 0:
                    raise ValueError("Step must be positive")

                if base == '*':
                    start = min_val
                    end = max_val + 1
                elif '-' in base:
                    try:
                        start, end = map(int, base.split('-'))
                        if start > end or start < min_val or end > max_val:
                            raise ValueError()
                    except (ValueError, IndexError):
                        raise ValueError(f"Invalid range: {base}")
                    end += 1
                else:
                    try:
                        val = int(base)
                        if val < min_val or val > max_val:
                            raise ValueError()
                        start = val
                        end = val + 1
                    except ValueError:
                        raise ValueError(f"Invalid value: {base}")

                for v in range(start, end, step):
                    values.add(v)
            elif '-' in part:
                try:
                    start, end = map(int, part.split('-'))
                    if start > end or start < min_val or end > max_val:
                        raise ValueError()
                except (ValueError, IndexError):
                    raise ValueError(f"Invalid range: {part}")
                for v in range(start, end + 1):
                    values.add(v)
            elif part == '*':
                for v in range(min_val, max_val + 1):
                    values.add(v)
            else:
                try:
                    val = int(part)
                    if val < min_val or val > max_val:
                        raise ValueError()
                except ValueError:
                    raise ValueError(f"Invalid value: {part}")
                values.add(val)

        return values

    # Parse each field
    try:
        minutes = parse_field(minute, 0, 59)
        hours = parse_field(hour, 0, 23)
        days_of_month = parse_field(dom, 1, 31)
        months = parse_field(month, 1, 12)
        days_of_week = parse_field(dow, 0, 6)
    except ValueError as e:
        raise ValueError(f"Malformed expression: {e}")

    # Helper to check if a date matches the cron
    def matches(dt):
        # Check month and hour/minute
        if dt.month not in months:
            return False
        if dt.hour not in hours:
            return False
        if dt.minute not in minutes:
            return False

        # Day matching logic
        dom_restricted = dom != '*'
        dow_restricted = dow != '*'

        if dom_restricted and dow_restricted:
            # Fire on day matching EITHER field
            if dt.day not in days_of_month and dt.weekday() != (days_of_week - {7} if 7 in days_of_week else set()):
                # Adjust weekday: cron uses Sunday=0, Python uses Monday=0
                if (dt.weekday() + 1) % 7 not in days_of_week:
                    return False
        elif dom_restricted:
            if dt.day not in days_of_month:
                return False
        elif dow_restricted:
            # Adjust weekday: cron uses Sunday=0, Python uses Monday=0
            if (dt.weekday() + 1) % 7 not in days_of_week:
                return False
        # else: both are *, so any day is fine

        return True

    # Start searching from the next minute
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Optimization: search in larger increments when possible
    max_days_to_check = 400  # Check up to ~1 year ahead

    for _ in range(max_days_to_check * 366):
        # Check if current date matches
        if matches(current):
            return current

        # Move to next minute
        current += timedelta(minutes=1)

        # Safety check: if we've gone too far, something is wrong
        if (current - after).days > 400:
            raise ValueError("No matching date found within reasonable time range")

    raise ValueError("No matching date found")
