def wildcard_match(pattern, s):
    m, n = len(pattern), len(s)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Handle patterns that start with '*' characters
    for i in range(1, m + 1):
        if pattern[i-1] == '*':
            dp[i][0] = dp[i-1][0]
        else:
            break

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[i-1] == '*':
                # '*' can match empty string (dp[i-1][j]) or one more char (dp[i][j-1])
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif pattern[i-1] == '?' or pattern[i-1] == s[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = False

    return dp[m][n]
