        if c.isspace():
            i += 1
            continue
        elif c.isdigit() or c == '.':
            j = i
            has_dot = False
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if has_dot:
                        raise ValueError("Invalid number format")
                    has_dot = True
                j += 1
            if expr[i] == '.' and (i == 0 or not expr[i-1].isdigit()):
                raise ValueError("Invalid number format")
            if j == i + 1 and expr[i] == '.':
                raise ValueError("Invalid number format")
            try:
                num = float(expr[i:j]) if has_dot else int(expr[i:j])
            except ValueError:
                raise ValueError("Invalid number format")
            tokens.append(num)
            i = j
        elif c in '+-*/%()':
            tokens.append(c)
            i += 1
        elif c == '^':
            # Convert ^ to ** for exponentiation
            tokens.append('**')
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    # Parse using recursive descent
    pos = [0]  # Use list to allow modification in nested functions

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def consume():
        token = tokens[pos[0]]
        pos[0] += 1
        return token

    def parse_expr():
        # Handle + and - (lowest precedence)
        left = parse_term()

        while peek() in ['+', '-']:
            op = consume()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term():
        # Handle *, /, % (medium precedence)
        left = parse_power()

        while peek() in ['*', '/', '%']:
            op = consume()
            right = parse_power()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ValueError("Division by zero")
                left = left / right
            else:  # %
                if right == 0:
                    raise ValueError("Modulo by zero")
                left = left % right

        return left

    def parse_power():
        # Handle ** (right-associative, higher than unary)
        base = parse_unary()

        if peek() == '**':
            consume()
            # Right-associative: parse the rest as power
            exponent = parse_power()
            return base ** exponent

        return base

    def parse_unary():
        # Handle unary + and -
        if peek() == '+':
            consume()
            return parse_unary()
        elif peek() == '-':
            consume()
            return -parse_unary()

        return parse_primary()

    def parse_primary():
        token = peek()

        if isinstance(token, (int, float)):
            consume()
            return token

        if token == '(':
            consume()  # consume '('
            result = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            consume()  # consume ')'
            return result

        if token is None:
            raise ValueError("Unexpected end of expression")

        # Handle invalid tokens
        if token in ['*', '/', '%', '**']:
            raise ValueError(f"Operator '{token}' cannot start operand")
        if token == ')':
            raise ValueError("Unexpected closing parenthesis")

        raise ValueError(f"Invalid expression at token: {token}")

    try:
        result = parse_expr()
        if pos[0] < len(tokens):
            raise ValueError("Unexpected token after expression")
        return result
    except IndexError:
        raise ValueError("Malformed expression")
