class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.snapshots = []
        self.n = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        # Union by size
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a

        # Record the change for rollback
        old_parent_b = self.parent[root_b]
        old_size_a = self.size[root_a]

        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]

        # Push the change to snapshots stack
        if not self.snapshots:
            self.snapshots.append([])
        self.snapshots[-1].append((root_b, old_parent_b, root_a, old_size_a))

        return True

    def snapshot(self):
        self.snapshots.append([])
        return len(self.snapshots) - 1

    def rollback(self, token):
        # Rollback all snapshots newer than the given token
        while self.snapshots and len(self.snapshots) - 1 > token:
            changes = self.snapshots.pop()
            # Process changes in reverse order
            for root_b, old_parent_b, root_a, old_size_a in reversed(changes):
                self.parent[root_b] = old_parent_b
                self.size[root_a] = old_size_a

        # If the token is still valid, remove snapshots up to and including it
        while self.snapshots and len(self.snapshots) - 1 >= token:
            self.snapshots.pop()

    def components(self):
        # Count roots
        return sum(1 for i in range(self.n) if self.parent[i] == i)
