class WildcardTrie:
    def __init__(self):
        self.root = {}
        self.counts = {}  # word -> count of occurrences

    def add(self, word):
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        # Mark end of word
        if '_end' not in node:
            node['_end'] = 0
        node['_end'] += 1

        # Track count of this word
        if word not in self.counts:
            self.counts[word] = 0
        self.counts[word] += 1

    def remove(self, word):
        if word not in self.counts or self.counts[word] == 0:
            return False

        # Decrement count
        self.counts[word] -= 1

        # Remove from trie if count reaches zero
        if self.counts[word] == 0:
            del self.counts[word]

            # Navigate to the end node and clean up
            node = self.root
            stack = []
            for char in word:
                stack.append((node, char))
                node = node[char]

            # Remove '_end' marker
            if '_end' in node:
                del node['_end']

            # Clean up empty nodes from the end backwards
            while stack:
                parent, char = stack.pop()
                if not node and len(node) == 0:  # node is empty dict
                    del parent[char]
                else:
                    break
