def deep_copy(obj):
    # Dictionary to track already copied objects to handle sharing and cycles
    seen = {}

    def _copy(obj):
        # Handle scalars (strings, ints, floats, bools, None)
        if isinstance(obj, (str, int, float, bool, type(None))):
            return obj

        # Handle already-seen objects (for cycles and sharing)
        if id(obj) in seen:
            return seen[id(obj)]

        # Handle lists
        if isinstance(obj, list):
            result = []
            seen[id(obj)] = result
            for item in obj:
                result.append(_copy(item))
            return result

        # Handle dicts
        if isinstance(obj, dict):
            result = {}
            seen[id(obj)] = result
            for key, value in obj.items():
                # Keys must also be copied if they're mutable
                copied_key = _copy(key)
                copied_value = _copy(value)
                result[copied_key] = copied_value
            return result

        # Handle sets
        if isinstance(obj, set):
            result = set()
            seen[id(obj)] = result
            for item in obj:
                result.add(_copy(item))
            return result

        # Handle tuples
        if isinstance(obj, tuple):
            seen[id(obj)] = obj  # Tuples are immutable, but we still need to track for sharing
            result_items = tuple(_copy(item) for item in obj)
            # Reuse original if no changes needed (for immutability and sharing)
            if result_items == obj:
                return obj
            seen[id(obj)] = result_items  # Update with actual tuple copy
            return result_items

        # Fallback for other types (shouldn't be needed per spec)
        return obj

