def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    # dist[node] = (total_cost, num_edges, path)
    dist = {src: (0, 0, [src])}

    # Priority queue: (cost, num_edges, path[-1], node)
    # Using path[-1] as tiebreaker for lexicographic comparison
    heap = [(0, 0, src, src)]

    while heap:
        cost, edges, last_node, node = heapq.heappop(heap)

        # Skip if we've found a better path to this node already
        if node in dist and (cost, edges) > dist[node][:2]:
            continue

        # If we reached destination, return immediately (Dijkstra guarantees optimality)
        if node == dst:
            return (cost, dist[node][2])

        # Explore neighbors
        if node in graph:
            for neighbor, weight in graph[node]:
                new_cost = cost + weight
                new_edges = edges + 1

                # Check if this path is better than existing known paths
                if neighbor not in dist or (new_cost, new_edges) < dist[neighbor][:2]:
                    # For tie-breaking on cost and edges, we need to compare lexicographically
                    new_path = dist[node][2] + [neighbor]

                    # Only update if strictly better
                    if neighbor not in dist or (new_cost, new_edges) < dist[neighbor][:2]:
                        dist[neighbor] = (new_cost, new_edges, new_path)
                        heapq.heappush(heap, (new_cost, new_edges, neighbor, neighbor))
                    elif (new_cost, new_edges) == dist[neighbor][:2]:
                        # Compare lexicographically
                        if new_path < dist[neighbor][2]:
                            dist[neighbor] = (new_cost, new_edges, new_path)
                            heapq.heappush(heap, (new_cost, new_edges, neighbor, neighbor))

