import heapq

def topo_lex(graph):
    # Count in-degrees for all nodes
    in_degree = {}

    # Collect all nodes (both keys and values)
    all_nodes = set(graph.keys())
    for successors in graph.values():
        all_nodes.update(successors)

    # Initialize in_degree for all nodes to 0
    for node in all_nodes:
        in_degree[node] = 0

    # Count in-degrees: for each node u, and each successor v (u->v),
    # increment in_degree[v]
    for node in graph:
        for successor in graph[node]:
            in_degree[successor] += 1

    # Initialize heap with all nodes having in-degree 0
    ready = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(ready, node)

    result = []

    while ready:
        # Get lexicographically smallest ready node
        node = heapq.heappop(ready)
        result.append(node)

        # Process all successors of this node
        for successor in graph.get(node, []):
            in_degree[successor] -= 1
            if in_degree[successor] == 0:
                heapq.heappush(ready, successor)

    # If we didn't process all nodes, there's a cycle
    if len(result) != len(all_nodes):
        return None

    return result
