function debounce(fn, wait, options) {
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let result = null;
  let leadingCalled = false;

  const clearTimer = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  const invokeFunc = () => {
    result = fn.apply(lastThis, lastArgs);
    leadingCalled = false;
  };

  const debounced = function(...args) {
    lastArgs = args;
    lastThis = this;

    const callNow = options && options.leading && !timeoutId && !leadingCalled;

    clearTimer();

    if (callNow) {
      leadingCalled = true;
      result = invokeFunc();
    } else if (options && options.trailing) {
      timeoutId = setTimeout(() => {
        invokeFunc();
      }, wait);
