function deepMerge(target, ...sources) {
  // Create a new object to avoid mutating target
  const result = Array.isArray(target) ? [...target] : { ...target };

  // Skip prototype pollution keys
  const isPrototypePollutionKey = (key) => 
    key === '__proto__' || key === 'constructor' || key === 'prototype';

  // Check if value is a plain object (not null, not array, not Date, etc.)
  const isPlainObject = (value) => 
    value !== null && typeof value === 'object' && !Array.isArray(value) && !(value instanceof Date);

  // Recursive merge function
  const merge = (targetObj, source) => {
    if (!isPlainObject(source)) {
      // If source is not a plain object, replace target with it (unless undefined)
      if (source !== undefined) {
        return source;
      }
      return targetObj;
    }

    // Create a new object to avoid mutation
    const merged = Array.isArray(targetObj) ? [...targetObj] : { ...targetObj };

    for (const key in source) {
      if (!Object.prototype.hasOwnProperty.call(source, key)) continue;

      // Skip prototype pollution keys
      if (isPrototypePollutionKey(key)) continue;

      const sourceValue = source[key];
      const targetValue = merged[key];

      // If source value is undefined, skip it
      if (sourceValue === undefined) continue;

      // If both values are plain objects, merge recursively
      if (isPlainObject(targetValue) && isPlainObject(sourceValue)) {
        merged[key] = merge(targetValue, sourceValue);
      } else {
        // Otherwise replace with source value (including null)
        merged[key] = sourceValue;
      }
    }

    return merged;
  };

  // Apply each source in order
  for (const source of sources) {
    if (source !== undefined && isPlainObject(source)) {
      // Create a fresh copy of result for each merge to avoid mutation
      const newResult = {};
      // Copy all properties from current result
      for (const key in result) {
        if (Object.prototype.hasOwnProperty.call(result, key)) {
          newResult[key] = result[key];
        }
      }
      // Merge source into the copy
      for (const key in source) {
        if (!Object.prototype.hasOwnProperty.call(source, key)) continue;

        // Skip prototype pollution keys
        if (isPrototypePollutionKey(key)) continue;

        const sourceValue = source[key];
        const targetValue = newResult[key];

        // If source value is undefined, skip it
        if (sourceValue === undefined) continue;

        // If both values are plain objects, merge recursively
        if (isPlainObject(targetValue) && isPlainObject(sourceValue)) {
          newResult[key] = merge(targetValue, sourceValue);
        } else {
          // Otherwise replace with source value (including null)
          newResult[key] = sourceValue;
        }
      }

      result = newResult;
    }
  }

  return result;
}

