class Emitter {
  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    const listeners = this.events.get(event);
    const index = listeners.push(fn) - 1;

    return () => {
      if (this.events.has(event)) {
        const idx = listeners.indexOf(fn);
        if (idx !== -1) {
          listeners.splice(idx, 1);
        }
      }
    };
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      return fn(...args);
    };
    // Store original function for off() to work
    wrapper.__original = fn;
    return this.on(event, wrapper);
  }

  off(event, fn) {
    if (!this.events.has(event)) return;

    const listeners = this.events.get(event);
    const index = listeners.indexOf(fn);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
  }

  emit(event, ...args) {
    if (!this.events.has(event)) return 0;

    // Create a copy of listeners to avoid issues with modifications during iteration
    const listeners = [...this.events.get(event)];
    let error = null;
    let count = 0;

    for (const listener of listeners) {
      try {
        listener(...args);
        count++;
      } catch (e) {
        if (!error) {
          error = e;
        }
      }
    }

    if (error) {
      throw error;
    }

    return count;
  }
}

module.exports = Emitter;
