function sqlTag(strings, ...values) {
  let text = '';
  let valuesArray = [];

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];

    if (i < values.length) {
      const value = values[i];

      if (value && typeof value === 'object' && !Array.isArray(value) && value.text !== undefined && value.values !== undefined) {
        // Inlined SQL result
        const offset = (text.match(/\$(\d+)/g) || []).length;
        const renumberedText = value.text.replace(/\$(\d+)/g, (_, num) => {
          return `$${Number(num) + offset}`;
        });
        text += renumberedText;
        valuesArray = valuesArray.concat(value.values);
      } else if (Array.isArray(value)) {
        // Array becomes parenthesized comma-separated list
        const placeholders = value.map((_, idx) => {
          valuesArray.push(value[idx]);
          return `$${valuesArray.length}`;
        });
        text += `(${placeholders.join(', ')})`;
      } else {
        // Simple value
        valuesArray.push(value);
        text += `$${valuesArray.length}`;
      }
    }
  }

  return {
    text,
    values: valuesArray
  };
}

