async function* chunkAsync(source, size) {
  if (typeof source[Symbol.asyncIterator] === 'function') {
    source = source[Symbol.asyncIterator]();
  } else if (typeof source[Symbol.iterator] === 'function') {
    // Convert sync iterator to async iterator wrapper
    const syncIter = source[Symbol.iterator]();
    source = {
      [Symbol.asyncIterator]() { return this; },
      async next() {
        const result = syncIter.next();
        return {
          value: result.value,
          done: result.done
        };
      },
      async return() {
        if (typeof syncIter.return === 'function') {
          return syncIter.return();
        }
        return { done: true, value: undefined };
      }
    };
  } else {
    throw new TypeError('source must be an async or sync iterable');
  }

  try {
    while (true) {
      const chunk = [];
      let i = 0;

      try {
        while (i < size) {
          const { value, done } = await source.next();
          if (done) break;
          chunk.push(value);
          i++;
        }
      } catch (e) {
        // If error occurs while reading, try to close source
        try { await source.return?.(); } catch (_) {}
        throw e;
      }

      if (chunk.length === 0) break;
      yield chunk;
    }
  } finally {
    try { await source.return?.(); } catch (_) {}
  }
}

