function memoize(fn, keyFn) {
  const cache = new Map();
  const weakCache = new WeakMap();
  let calls = 0;

  function getCacheKey(args) {
    if (keyFn) {
      return keyFn(...args);
    }

    if (args.length !== 1) {
      // For multiple arguments, use a composite key
      return JSON.stringify(args);
    }

    const arg = args[0];
    if (arg !== null && typeof arg === 'object') {
      // Use WeakMap for objects
      return { type: 'weak', value: arg };
    }

    // Use regular Map for primitives
    return { type: 'primitive', value: arg };
  }

  function memoized(...args) {
    const cacheKey = getCacheKey(args);

    // Check WeakMap first for object keys
    if (cacheKey.type === 'weak') {
      if (weakCache.has(cacheKey.value)) {
        return weakCache.get(cacheKey.value);
      }
    } else if (cache.has(cacheKey)) {
      return cache.get(cacheKey);
    }

    // Compute result
    const result = fn(...args);

    // Only cache if no exception was thrown (if we got here, no exception)
    calls++;

    // Cache the result
    if (cacheKey.type === 'weak') {
      weakCache.set(cacheKey.value, result);
    } else {
      cache.set(cacheKey, result);
    }

    return result;
  }

  memoized.cache = cache;
  memoized.weakCache = weakCache;
  memoized.calls = () => calls;
  memoized.clear = function() {
    cache.clear();
    weakCache.clear();
    calls = 0;
  };

  return memoized;
}

module.exports = memoize;
