function* zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iterators = iterables.map(iterable => iterable[Symbol.iterator]());
  const doneFlags = new Array(iterators.length).fill(false);

  while (true) {
    const row = [];
    let allDone = true;

    for (let i = 0; i < iterators.length; i++) {
      if (!doneFlags[i]) {
        const result = iterators[i].next();
        if (result.done) {
          doneFlags[i] = true;
          row.push(fill);
        } else {
          row.push(result.value);
          allDone = false;
        }
      } else {
        row.push(fill);
      }
    }

    if (allDone) break;
    yield row;
  }
}

