function createStore(reducer, initial) {
  let state = typeof initial !== 'undefined' ? initial : reducer(undefined, { type: '@@INIT' });
  let currentListeners = [];
  let nextListeners = currentListeners;
  let isDispatching = false;

  function getState() {
    return state;
  }

  function subscribe(listener) {
    if (typeof listener !== 'function') {
      throw new Error('Expected listener to be a function.');
    }

    let isSubscribed = true;

    function unsubscribe() {
      if (!isSubscribed) return;
      isSubscribed = false;

      if (isDispatching) {
        throw new Error('You may not unsubscribe from a store while it is dispatching.');
      }

      let index = nextListeners.indexOf(listener);
      if (index !== -1) {
        nextListeners.splice(index, 1);
      }
    }

    if (isDispatching) {
      throw new Error('You may not call subscribe() while the store is dispatching.');
    }

    nextListeners.push(listener);
    return unsubscribe;
  }

  function dispatch(action) {
    if (typeof action === 'undefined') {
      throw new Error('Actions must be plain objects. Use custom middleware for async actions.');
    }

    if (isDispatching) {
      throw new Error('Reducers may not dispatch actions.');
    }

    try {
      isDispatching = true;
      state = reducer(state, action);
    } finally {
      isDispatching = false;
    }

    const listeners = (currentListeners = nextListeners);
    for (let i = 0; i < listeners.length; i++) {
      const listener = listeners[i];
      listener();
    }

    return action;
  }

  // Initialize the store with a dummy action
  dispatch({ type: '@@INIT' });

  return {
    getState,
    dispatch,
    subscribe
  };
}

module.exports = createStore;
