module.exports = async function toposortTasks(tasks) {
  if (!tasks || typeof tasks !== 'object') {
    throw new Error('Invalid tasks input');
  }

  const visited = new Set();
  const visiting = new Set();
  const result = {};
  let error = null;

  // Build dependency graph and validate dependencies
  for (const [name, task] of Object.entries(tasks)) {
    if (!task || typeof task !== 'object' || !Array.isArray(task.deps) || typeof task.run !== 'function') {
      throw new Error(`Invalid task definition for "${name}"`);
    }

    // Check for unknown dependencies
    for (const dep of task.deps) {
      if (!(dep in tasks)) {
        throw new Error(`Unknown dependency "${dep}" for task "${name}"`);
      }
    }
  }

  // DFS to detect cycles and build topological order
  const dfs = (name) => {
    if (error) return;

    if (visited.has(name)) return;

    if (visiting.has(name)) {
      error = new Error(`cycle detected involving task "${name}"`);
      return;
    }

    visiting.add(name);

    const task = tasks[name];
    for (const dep of task.deps) {
      dfs(dep);
      if (error) return;
    }

    visiting.delete(name);
    visited.add(name);
  };

  // Run DFS on all tasks to detect cycles
  for (const name of Object.keys(tasks)) {
    dfs(name);
    if (error) throw error;
  }

  // Process tasks in topological order
  const processTask = async (name) => {
    if (result.hasOwnProperty(name)) return result[name];

    const task = tasks[name];
    const depValues = {};

    // Wait for all dependencies to complete
    await Promise.all(task.deps.map(async (dep) => {
      try {
        depValues[dep] = await processTask(dep);
      } catch (err) {
        // If any dependency fails, we still need to let other tasks complete
        if (!error) {
          error = err;
        }
      }
    }));

    // If an error occurred in dependencies, throw it
    if (error) {
      throw error;
    }

    // Run the task with resolved dependency values
    try {
      const value = await task.run(depValues);
      result[name] = value;
      return value;
    } catch (err) {
      if (!error) {
        error = err;
      }
      throw err;
    }
  };

  // Start processing all tasks
  const promises = Object.keys(tasks).map(name => processTask(name));

  try {
    await Promise.all(promises);
  } catch (err) {
    // Wait for all tasks to complete even if one fails
    await Promise.allSettled(promises);
    throw error || err;
  }

  return result;
};
