      const currentSet = this.handlers.get(k);
      if (currentSet) {
        currentSet.delete(fn as (payload: E[keyof E]) => void);
        if (currentSet.size === 0) {
          this.handlers.delete(k);
        }
      }
    };
  }

  emit<K extends keyof E>(k: K, ...args: E[K] extends void ? [] : [payload: E[K]]): void {
    const set = this.handlers.get(k);
    if (!set) return;

    // Runtime check: ensure correct number of arguments
    const expectedArgCount = E[k] extends void ? 0 : 1;
    if (args.length !== expectedArgCount) {
      throw new Error(
        `emit('${String(k)}'): Expected ${expectedArgCount} argument(s), got ${args.length}`
      );
    }

    const payload = (args[0] as E[K]) ?? undefined;
    for (const handler of set) {
      // Type-safe call: cast to any to allow runtime dispatch
      (handler as (...args: unknown[]) => void)(payload);
    }
  }
}
