export function match<T extends { kind: string }, R>(
  value: T,
  handlers: {
    [K in T['kind']]: (value: Extract<T, { kind: K }>) => R
  }
): R {
  const handler = handlers[value.kind as keyof typeof handlers];
  if (!handler) {
    throw new Error(`No handler for kind: ${value.kind}`);
  }
  return handler(value as Extract<T, { kind: keyof typeof handlers }>);
}
