type RequiredKeys<T> = { [K in keyof T]: {} extends Pick<T, K> ? never : K }[keyof T];
type OptionalKeys<T> = { [K in keyof T]: {} extends Pick<T, K> ? K : never }[keyof T];

interface BuilderState<Config> {
  setKeys: Set<keyof Config>;
}

class Builder<Config> {
  private state: BuilderState<Config> = { setKeys: new Set() };

  set<K extends keyof Config>(key: K, value: Config[K]): this {
    // Type-checking is enforced by the parameter types
    (this.state.setKeys as Set<K>).add(key);
    return this;
  }

  build(): Config {
    const requiredKeys: RequiredKeys<Config>[] = Object.keys(
      {} as { [K in keyof Config]: {} extends Pick<Config, K> ? never : K }
    ) as RequiredKeys<Config>[];

    const missingRequired = requiredKeys.filter(
      k => !this.state.setKeys.has(k)
    );

    if (missingRequired.length > 0) {
      throw new Error(`Missing required keys: ${missingRequired.join(', ')}`);
    }

    // Return a partial object that satisfies all required keys
    const result = {} as Config;
    for (const key of this.state.setKeys) {
      // This cast is safe because we only allow setting known keys
      (result as any)[key] = undefined;
    }

    // This is a type assertion; in practice, the caller must ensure all required keys are set
    // before calling build(). The runtime check above enforces this.
    return result as Config;
  }
}

export function builder<Config>(): Builder<Config> {
  return new Builder<Config>();
}
