export type Brand<T, B extends string> = T & { readonly __brand: unique symbol; readonly brand: B };

export type Email = Brand<string, 'Email'>;

export const isEmail = (s: string): s is Email => {
  // Basic email regex for demonstration; in production use a more robust validator
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(s);
};

export const asEmail = (s: string): Email => {
  if (!isEmail(s)) {
    throw new Error(`Invalid email address: "${s}"`);
  }
  return s as Email;
};
