export type DeepPartial<T> = T extends Function
  ? T
  : T extends Array<infer U>
    ? T
    : { [K in keyof T]?: DeepPartial<T[K]> };

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === null || typeof patch !== 'object') {
    return patch as T;
  }

  if (Array.isArray(patch)) {
    // Replace arrays wholesale
    return patch as T;
  }

  const result = { ...base } as T;

  for (const key in patch) {
    if (Object.prototype.hasOwnProperty.call(patch, key)) {
      const value = patch[key as keyof DeepPartial<T>];

      if (value === undefined) {
        // Explicit undefined means leave alone
        continue;
      }

      const baseValue = result[key as keyof T];

      if (
        baseValue !== null &&
        typeof baseValue === 'object' &&
        !Array.isArray(baseValue) &&
        value !== null &&
        typeof value === 'object' &&
        !Array.isArray(value)
      ) {
        // Recursively merge objects
        result[key as keyof T] = applyPatch(baseValue, value);
      } else {
        // Replace (including arrays and primitives)
        result[key as keyof T] = value;
      }
    }
  }

  return result;
}
